+/** `rotation` を書いた `badge` を、その編集で置き直したあとの `badge` の props。 */
+function repositionRotatedBadge(
+  rotation: PropValue,
+  edit: RepositionEdit,
+): Readonly<Record<string, unknown>> {
+  return badgePropsOf(
+    Result.unwrap(
+      DesignDocument.reposition(
+        setupRotatedBadgeDocument(rotation),
+        "badge",
+        edit,
+      ),
     ),
   );
 }
