+            name: "frame",
+            type: "Box",
+            props: {
+              placement: "absolute",
+              x: 100,
+              y: 50,
+              width: 200,
+              height: 100,
+              rotation: 90,
+            },
+            children: [
+              {
+                name: "chip",
+                type: "Text",
+                props: { content: "c", placement: "absolute", x: 10, y: 10 },
+              },
+              {
+                name: "peg",
+                type: "Text",
+                props: { content: "p", placement: "absolute", x: 150, y: 60 },
+              },
+            ],
+          },
+          {
+            name: "pin",
+            type: "Text",
+            props: { content: "x", placement: "absolute", x: 20, y: 150 },
+          },
+        ],
+      }),
+    ],
+  });
